"use strict";document.addEventListener("DOMContentLoaded",()=>{const t=document.getElementById("controlReportPdfButton");if(!t||t.disabled)return;const validationError=t=>Swal.fire({icon:"error",title:"Μη έγκυρα κριτήρια",text:t});t.addEventListener("click",()=>{const t=String(document.getElementById("apo_hmeromhnia")?.value||"").trim(),e=String(document.getElementById("eos_hmeromhnia")?.value||"").trim(),n=String(document.getElementById("ypokatasthma_stathera_advanced")?.value||"").trim();if(!t)return validationError("Συμπληρώστε την Από Ημερομηνία.");if(!e)return validationError("Συμπληρώστε την Έως Ημερομηνία.");if(t>e)return validationError("Η Από Ημερομηνία δεν μπορεί να είναι μετά την Έως Ημερομηνία.");if(!/^\d{1,4}$/.test(n)||"ALL"===n.toUpperCase()||n.includes(","))return validationError("Επιλέξτε ένα συγκεκριμένο παράρτημα.");const a=new URLSearchParams({ypokatasthma:n.padStart(4,"0"),apo_hmeromhnia:t,eos_hmeromhnia:e});window.open(`/ergazomenoi/programmata/katastashElegxouApologistikouPinaka/pdf?${a.toString()}`,"_blank","noopener")})});